import sqlite3

# Veritabanı bağlantısı
DB_NAME = "magaza.db"

# SQL Sorgusu - Tek string içinde ve kontrol edildi
sql_query = "WITH KategoriCiro2025 AS (
  SELECT
    u.kategori,
    COALESCE(SUM(skl.adet * skl.birim_fiyat), 0.0) AS ciro_2025
  FROM urunler u
  JOIN siparis_kalemleri skl ON u.id = skl.urun_id
  JOIN siparisler s ON skl.siparis_id = s.id
  WHERE s.tarih LIKE '2025-%'
  GROUP BY u.kategori
),
TumKategoriler AS (
  SELECT DISTINCT kategori FROM urunler
),
ToplamCiro2025 AS (
  SELECT COALESCE(SUM(ciro_2025), 0.0) AS toplam_ciro FROM KategoriCiro2025
)
SELECT
  tk.kategori,
  ROUND(COALESCE(kc.ciro_2025, 0.0), 2) AS ciro,
  ROUND((COALESCE(kc.ciro_2025, 0.0) * 100.0) / (SELECT toplam_ciro FROM ToplamCiro2025), 1) AS yuzde,
  DENSE_RANK() OVER (
    ORDER BY COALESCE(kc.ciro_2025, 0.0) DESC, tk.kategori ASC
  ) AS sira
FROM TumKategoriler tk
LEFT JOIN KategoriCiro2025 kc ON tk.kategori = kc.kategori
ORDER BY
  sira, tk.kategori ASC;"

# Test amaçlı veritabanı oluşturma ve doldurma
try:
    conn = sqlite3.connect(DB_NAME)
    cursor = conn.cursor()

    # Şema oluşturma (varsa silip yeniden oluşturma)
    cursor.execute("DROP TABLE IF EXISTS musteriler")
    cursor.execute("DROP TABLE IF EXISTS urunler")
    cursor.execute("DROP TABLE IF EXISTS siparisler")
    cursor.execute("DROP TABLE IF EXISTS siparis_kalemleri")
    cursor.execute("DROP TABLE IF EXISTS iadeler")

    # Şemayı oluştur
    cursor.executescript(""
CREATE TABLE musteriler (id INTEGER PRIMARY KEY, ad TEXT NOT NULL, sehir TEXT NOT NULL, kayit_tarihi TEXT NOT NULL);
CREATE TABLE urunler (id INTEGER PRIMARY KEY, ad TEXT NOT NULL, kategori TEXT NOT NULL, fiyat REAL NOT NULL);
CREATE TABLE siparisler (id INTEGER PRIMARY KEY, musteri_id INTEGER NOT NULL REFERENCES musteriler(id), tarih TEXT NOT NULL);
CREATE TABLE siparis_kalemleri (siparis_id INTEGER NOT NULL REFERENCES siparisler(id), urun_id INTEGER NOT NULL REFERENCES urunler(id), adet INTEGER NOT NULL, birim_fiyat REAL NOT NULL);
CREATE TABLE iadeler (id INTEGER PRIMARY KEY, siparis_id INTEGER NOT NULL REFERENCES siparisler(id), urun_id INTEGER NOT NULL REFERENCES urunler(id), adet INTEGER NOT NULL);
")

    # Test verisi ekleme (2025 ve 2024 karışık)
    cursor.executemany("INSERT INTO musteriler (id, ad, sehir, kayit_tarihi) VALUES (?, ?, ?, ?)", [(1, 'Ali', 'Ankara', '2024-01-01')]);

    # Ürünler: Elektronik, Kitap, Giyim, Oyun
    cursor.executemany("INSERT INTO urunler (id, ad, kategori, fiyat) VALUES (?, ?, ?, ?)", [(101, 'Laptop', 'Elektronik', 20000.0), (102, 'Kitap A', 'Kitap', 50.0), (103, 'Tişört', 'Giyim', 150.0), (104, 'Telefon', 'Elektronik', 15000.0), (105, 'Oyuncak', 'Oyun', 100.0)]);

    # Siparişler
    cursor.execute("INSERT INTO siparisler (id, musteri_id, tarih) VALUES (1, 1, '2025-03-10')");
    cursor.execute("INSERT INTO siparisler (id, musteri_id, tarih) VALUES (2, 1, '2025-05-20')");
    cursor.execute("INSERT INTO siparisler (id, musteri_id, tarih) VALUES (3, 1, '2025-07-01')");
    cursor.execute("INSERT INTO siparisler (id, musteri_id, tarih) VALUES (4, 1, '2024-11-01')");

    # Sipariş Kalemleri (2025 Ciro Hesaplaması)
    cursor.execute("INSERT INTO siparis_kalemleri (siparis_id, urun_id, adet, birim_fiyat) VALUES (1, 101, 1, 20000.0)");
    cursor.execute("INSERT INTO siparis_kalemleri (siparis_id, urun_id, adet, birim_fiyat) VALUES (1, 102, 1, 50.0)");
    cursor.execute("INSERT INTO siparis_kalemleri (siparis_id, urun_id, adet, birim_fiyat) VALUES (2, 104, 1, 15000.0)");
    cursor.execute("INSERT INTO siparis_kalemleri (siparis_id, urun_id, adet, birim_fiyat) VALUES (3, 103, 1, 150.0)");
    cursor.execute("INSERT INTO siparis_kalemleri (siparis_id, urun_id, adet, birim_fiyat) VALUES (3, 104, 1, 15000.0)");

    # Sorguyu çalıştır
    cursor.execute(sql_query)
    results = cursor.fetchall()

    # Sonuçları dosyaya yaz
    with open("cevap.sql", "w") as f:
        f.write(sql_query)

    print("Sorgu başarıyla yazıldı ve test verisi ile çalıştırıldı. Sonuçlar (test için) elde edildi.")
    # İstenen sütun sırasına göre çıktı formatı: kategori, ciro, yüzde, sıra
    print("--- TEST SONUÇLARI (İstenen Format) ---")
    for row in results:
        print(f"{row[0]}, {row[1]:.2f}, {row[2]:.1f}, {row[3]}")

    conn.close()

except sqlite3.Error as e:
    print(f"SQLite Hatası oluştu: {e}")
except Exception as e:
    print(f"Beklenmedik Hata: {e}")

